CREATE VIEW v_post_user AS SELECT posts.Id AS post_id, posts.PostTypeId AS post_type_id, posts.Score AS post_score, posts.ViewCount AS view_count, posts.Title AS post_title, posts.Tags AS post_tags, posts.AnswerCount AS answer_count, posts.CommentCount AS comment_count, posts.FavoriteCount AS favorite_count, users.Id AS user_id, users.DisplayName AS author_name, users.Reputation AS author_reputation, users.Location AS author_location, users.Views AS author_views, users.UpVotes AS author_upvotes, users.DownVotes AS author_downvotes, posts.AcceptedAnswerId, posts.CreaionDate, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName, users.CreationDate, users.LastAccessDate, users.WebsiteUrl, users.AboutMe, users.AccountId, users.Age, users.ProfileImageUrl FROM posts LEFT JOIN users ON posts.OwnerUserId = users.Id;

CREATE VIEW v_comment_details AS SELECT comments.Id AS comment_id, comments.Score AS comment_score, comments.Text AS comment_text, comments.CreationDate AS comment_date, posts.Id AS post_id, posts.Title AS post_title, users.Id AS user_id, users.DisplayName AS commenter_name, users.Reputation AS commenter_reputation, comments.PostId, comments.UserId, comments.UserDisplayName, posts.PostTypeId, posts.AcceptedAnswerId, posts.CreaionDate, posts.Score, posts.ViewCount, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.Tags, posts.AnswerCount, posts.CommentCount, posts.FavoriteCount, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName, users.CreationDate, users.LastAccessDate, users.WebsiteUrl, users.Location, users.AboutMe, users.Views, users.UpVotes, users.DownVotes, users.AccountId, users.Age, users.ProfileImageUrl FROM comments LEFT JOIN posts ON comments.PostId = posts.Id LEFT JOIN users ON comments.UserId = users.Id;

CREATE VIEW v_badges AS SELECT badges.Id, badges.UserId, badges.Name, badges.Date, users.Id AS users_Id, users.Reputation, users.CreationDate, users.DisplayName, users.LastAccessDate, users.WebsiteUrl, users.Location, users.AboutMe, users.Views, users.UpVotes, users.DownVotes, users.AccountId, users.Age, users.ProfileImageUrl FROM badges LEFT JOIN users ON badges.UserId = users.Id;

CREATE VIEW v_posthistory AS SELECT postHistory.Id, postHistory.PostHistoryTypeId, postHistory.PostId, postHistory.RevisionGUID, postHistory.CreationDate, postHistory.UserId, postHistory.Text, postHistory.Comment, postHistory.UserDisplayName, users.Id AS users_Id, users.Reputation, users.CreationDate AS users_CreationDate, users.DisplayName, users.LastAccessDate, users.WebsiteUrl, users.Location, users.AboutMe, users.Views, users.UpVotes, users.DownVotes, users.AccountId, users.Age, users.ProfileImageUrl, posts.Id AS posts_Id, posts.PostTypeId, posts.AcceptedAnswerId, posts.CreaionDate, posts.Score, posts.ViewCount, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.Title, posts.Tags, posts.AnswerCount, posts.CommentCount, posts.FavoriteCount, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName FROM postHistory LEFT JOIN users ON postHistory.UserId = users.Id LEFT JOIN posts ON postHistory.PostId = posts.Id;

CREATE VIEW v_postlinks AS SELECT postLinks.Id, postLinks.CreationDate, postLinks.PostId, postLinks.RelatedPostId, postLinks.LinkTypeId, posts.Id AS posts_Id, posts.PostTypeId, posts.AcceptedAnswerId, posts.CreaionDate, posts.Score, posts.ViewCount, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.Title, posts.Tags, posts.AnswerCount, posts.CommentCount, posts.FavoriteCount, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName, posts_2.Id AS posts_2_Id, posts_2.PostTypeId AS posts_2_PostTypeId, posts_2.AcceptedAnswerId AS posts_2_AcceptedAnswerId, posts_2.CreaionDate AS posts_2_CreaionDate, posts_2.Score AS posts_2_Score, posts_2.ViewCount AS posts_2_ViewCount, posts_2.Body AS posts_2_Body, posts_2.OwnerUserId AS posts_2_OwnerUserId, posts_2.LasActivityDate AS posts_2_LasActivityDate, posts_2.Title AS posts_2_Title, posts_2.Tags AS posts_2_Tags, posts_2.AnswerCount AS posts_2_AnswerCount, posts_2.CommentCount AS posts_2_CommentCount, posts_2.FavoriteCount AS posts_2_FavoriteCount, posts_2.LastEditorUserId AS posts_2_LastEditorUserId, posts_2.LastEditDate AS posts_2_LastEditDate, posts_2.CommunityOwnedDate AS posts_2_CommunityOwnedDate, posts_2.ParentId AS posts_2_ParentId, posts_2.ClosedDate AS posts_2_ClosedDate, posts_2.OwnerDisplayName AS posts_2_OwnerDisplayName, posts_2.LastEditorDisplayName AS posts_2_LastEditorDisplayName FROM postLinks LEFT JOIN posts ON postLinks.RelatedPostId = posts.Id LEFT JOIN posts AS posts_2 ON postLinks.PostId = posts_2.Id;

CREATE VIEW v_tags AS SELECT tags.Id, tags.TagName, tags.Count, tags.ExcerptPostId, tags.WikiPostId, posts.Id AS posts_Id, posts.PostTypeId, posts.AcceptedAnswerId, posts.CreaionDate, posts.Score, posts.ViewCount, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.Title, posts.Tags, posts.AnswerCount, posts.CommentCount, posts.FavoriteCount, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName FROM tags LEFT JOIN posts ON tags.ExcerptPostId = posts.Id;

CREATE VIEW v_votes AS SELECT votes.Id, votes.PostId, votes.VoteTypeId, votes.CreationDate, votes.UserId, votes.BountyAmount, users.Id AS users_Id, users.Reputation, users.CreationDate AS users_CreationDate, users.DisplayName, users.LastAccessDate, users.WebsiteUrl, users.Location, users.AboutMe, users.Views, users.UpVotes, users.DownVotes, users.AccountId, users.Age, users.ProfileImageUrl, posts.Id AS posts_Id, posts.PostTypeId, posts.AcceptedAnswerId, posts.CreaionDate, posts.Score, posts.ViewCount, posts.Body, posts.OwnerUserId, posts.LasActivityDate, posts.Title, posts.Tags, posts.AnswerCount, posts.CommentCount, posts.FavoriteCount, posts.LastEditorUserId, posts.LastEditDate, posts.CommunityOwnedDate, posts.ParentId, posts.ClosedDate, posts.OwnerDisplayName, posts.LastEditorDisplayName FROM votes LEFT JOIN users ON votes.UserId = users.Id LEFT JOIN posts ON votes.PostId = posts.Id;
